\caption{$\texttt{Riemannian Hamiltonian Monte Carlo}$}\label{alg:RHMC}

\SetAlgoLined

\textbf{Input:} Initial point $x$, step size $h$

\tcp{Step 1: Sample an initial velocity $v$}

Sample $v\sim\mathcal{N}(0,g(x))$.

\ 

\tcp{Step 2: Solve the Hamiltonian equations}

Solve the Hamiltonian equations (\ref{eq:hmc_intro}) to obtain $(x(t),v(t))$.

\

\tcp{Step 3: Metropolis-filter (skipped for ideal RHMC)}
Accept $x(h)$ with probability $\min \Par{1 , \frac{e^{-H(x(h),v(h))}}{e^{-H(x,v)}}}$. 
Otherwise, stay at $x$.

When defining smoothness parameters, \cite{lee2018convergence} pays attention to ``well-behaved'' Hamiltonian curves $\gamma$ starting at \emph{any} point in $\mathbb{\mathcal{M}}$, where the well-behavedness may be viewed as the
average behavior of Hamiltonian curves with \emph{high probability}
and is quantified by some auxiliary function.

 The probability density
of one-step distribution of RHMC at $x\in\mathbb{\mathcal{M}}\subset\mathbb{R}^{n}$ is 
\begin{equation}
p_{x}(z)=\sum_{v_{x}:\mathrm{Ham}_{x,h}(v_{x})=z}\underbrace{\Abs{D\mathrm{Ham}_{x,h}(v_{x})}^{-1}\sqrt{\frac{\Abs{g(z)}}{(2\pi)^{n}}}\exp\Par{-\frac{1}{2}\norm{v_{x}}_{x}^{2}}}_{\stackrel{\mathrm{{\scriptscriptstyle def}}}{=} p_{x}^{0}(v_{x})}.\label{eq:densityOneStep}
\end{equation}

