\end{align*}
Fact 10 follows from the following computation: 
\begin{align*}
\norm{g^{-1} p-g'^{-1}q}_{g} & \leq\norm{g^{-1}(p-q)+(g^{-1}-g'^{-1})q}_{g}\leq\norm{p-q}_{g^{-1}}+\underbrace{O(\delta_{x})\norm q_{g^{-1}}}_{\text{Fact 9}}.
\end{align*}
Fact 11 follows from the following computation and Fact 10: 
\begin{align*}
\norm{\frac{\mathcal{\partial} H}{\mathcal{\partial} v}(x,v)-\frac{\mathcal{\partial} H}{\mathcal{\partial} v}(x',v')}_{g} & =\norm{g^{-1}v-g'^{-1}v'}_{g}\leq\delta_{v}+O(\delta_{x})\norm{v'}_{g^{-1}}.
\end{align*}
For Fact 12, we note that 
\begin{align*}
\frac{\mathcal{\partial} H}{\mathcal{\partial} x}(x,v)-\frac{\mathcal{\partial} H}{\mathcal{\partial} x}(x',v') & =\Par{\nabla f(x)-\nabla f(x')}\\
 & \ \ -\frac{1}{2}\Par{Dg\Brack{g^{-1} v,g^{-1} v}-Dg'\Brack{g'^{-1}v,g'^{-1}v}}+\frac{1}{2}\Par{\mathrm{Tr}(g^{-1}Dg)-\mathrm{Tr}(g'^{-1}Dg')}\\
