 & ~~+\frac{1}{2}\Par{\underbrace{\mathrm{Tr}(g^{-1}Dg-g'^{-1}Dg)}_{T}+\underbrace{\mathrm{Tr}(g'^{-1}Dg-g'^{-1}Dg')}_{R}}+\Par{\nabla f(x)-\nabla f(x')}.
\end{align*}
For $F$, by the third fact in Lemma \ref{lem:sc_facts} 
\begin{align*}
\norm F_{g^{-1}} & \lesssim\frac{1}{(1-\delta_{x})^{3}}\norm{g^{-1}v}_{g}^{2}\norm{x-x'}_{g}=\frac{1}{(1-\delta_{x})^{3}}\norm v_{g^{-1}}^{2}\delta_{x}\lesssim\delta_{x}\norm v_{g^{-1}}^{2}.
\end{align*}
For $S$, by the fourth fact in Lemma \ref{lem:sc_facts} 
\begin{align*}
\norm S_{g^{-1}} & \lesssim\norm S_{g'^{-1}}\lesssim\norm{g^{-1}v-g'^{-1}v'}_{g'}\norm{g^{-1}v+g'^{-1}v'}_{g'}\\
 & \lesssim\Par{\norm{v-v'}_{g'^{-1}}+O(\delta_{x})\norm v_{g'^{-1}}}\Par{\norm v_{g'^{-1}}+\norm{v'}_{g'^{-1}}}\\
 & \lesssim\Par{\delta_{v}+\delta_{x}\norm v_{g^{-1}}}\Par{\norm v_{g'^{-1}}+\norm{v'}_{g'^{-1}}}.
\end{align*}
For $T$, using the stochastic estimator of trace 
\begin{align*}
\norm{\mathrm{Tr}\Par{g^{-1}Dg-g'^{-1}Dg}}_{g^{-1}} & =\max_{\norm u_{g}=1}\mathrm{Tr}\Par{(g^{-1}-g'^{-1})Dg[u]}\\
 & =\max_{\norm u_{g}=1}\mathrm{Tr}\Par{g^{\frac{1}{2}}(g^{-1}-g'^{-1})Dg[u]g^{-\frac{1}{2}}}\\
 & =\max_{\norm u_{g}=1}\mathbb{E}_{z\sim\mathcal{N}(0,I)}\Brack{z^{\top}g^{\frac{1}{2}}(g^{-1}-g'^{-1})Dg[u]g^{-\frac{1}{2}}z}\\
 & =\max_{\norm u_{g}=1}\mathbb{E} Dg\Brack{u,g^{-\frac{1}{2}}z,(g^{-1}-g'^{-1})g^{\frac{1}{2}}z}\\
 & \leq2\mathbb{E}\max_{\norm u_{g}=1}\norm u_{g}\norm{g^{-\frac{1}{2}}z}_{g}\underbrace{\norm{\Par{g^{-1}-g'^{-1}}g^{\frac{1}{2}}z}_{g}}_{\text{Fact 9}}\\
 & \leq O(\delta_{x})\mathbb{E}\norm z_{2}\norm{g^{\frac{1}{2}}z}_{g^{-1}}=O(\delta_{x})\mathbb{E}\norm z_{2}^{2}\\
 & =O(n\delta_{x}).
\end{align*}
For $R$, in a similar way that we bounded $\norm T_{g^{-1}}$ 
\begin{align*}
\norm{\mathrm{Tr}\Par{g'^{-1}Dg-g'^{-1}Dg'}}_{g^{-1}} & =\norm{\mathbb{E}_{z\sim\mathcal{N}(0,I)}\Par{Dg[g'^{-\frac{1}{2}}z,g'^{-\frac{1}{2}}z]-Dg'[g'^{-\frac{1}{2}}z,g'^{-\frac{1}{2}}z]}}_{g^{-1}}\\
 & \leq\mathbb{E}\underbrace{\ginvnorm{Dg[g'^{-\frac{1}{2}}z,g'^{-\frac{1}{2}}z]-Dg'[g'^{-\frac{1}{2}}z,g'^{-\frac{1}{2}}z]}}_{\text{Use Lemma~\ref{lem:sc_facts}}}\\
